  nextListening(){const prompt=this.listenSession.next(nowSeed()+this.sequence++);this.listenState=null;this.listenReveal=false;this.listenResult=null;this.reveal=false;this.inputText='';this.completed=false;this.mode='english';this.evidence=new AttemptEvidence();this.target=prompt?.text??'';this.guide=prompt?.guide??this.plan(this.target,'english');this.resetGuideProgress();this.render();if(prompt)this.speakWord();else if(this.listenSession.isSessionComplete)this.announce('Ten-word listening session complete.');}
