function sourceHash(sources){let value=2166136261;for(const c of JSON.stringify(sources)){value^=c.charCodeAt(0);value=Math.imul(value,16777619);}return(value>>>0).toString(16);}
function pText(count){return`${count} use ${count===1?'reflection':'reflections'}`;}
